{"id":"aecabe43-0e63-4408-98fe-5119c9835597","type":"https://serlo.org/editor","variant":"serlo-org","domainOrigin":"serlo.org","version":2,"editorVersion":"0.22.0","dateModified":"2025-02-26T18:24:29.542Z","document":{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Drücke die Wahrscheinlichkeit für das Ereignis "},{"type":"math","src":"E = "\text{entweder} \;A\;\text{oder}\;B" ","inline":true,"children":[{"text":""\text{entweder} \;A\text{oder}\;B""}]},{"text":" durch die Wahrscheinlichkeiten der Ereignisse "},{"type":"math","src":"A","inline":true,"children":[{"text":"A"}]},{"text":", "},{"type":"math","src":"B","inline":true,"children":[{"text":"B"}]},{"text":" und "},{"type":"math","src":"A\cap B","inline":true,"children":[{"text":"A\cap B"}]},{"text":" aus."}]}],"id":"508dc31a-09c4-4be2-9cef-4b36b230a930"}],"id":"ab481918-946d-41b4-99de-cd64343eca93"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"1753","title":"Wahrscheinlichkeit"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"407a4984-a0d8-4957-90b5-d1c277539b85"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Das Ereignis "},{"type":"math","src":""\text{entweder} \;A\;\text{oder}\;B"","inline":true,"children":[{"text":""\text{entweder} \;A\;\text{oder}\;B""}]},{"text":" bedeutet, dass nur das Ereignis "},{"type":"math","src":"A","inline":true,"children":[{"text":"A"}]},{"text":" oder nur das Ereignis "},{"type":"math","src":"B","inline":true,"children":[{"text":"B"}]},{"text":" eintritt, jedoch nicht beide gleichzeitig."}]}],"id":"c7ffb71c-abe8-4b85-aec3-3dedbf2f6943"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Die Wahrscheinlichkeit, dass das Ereignis "},{"type":"math","src":""A \;\text{oder}\; B"","inline":true,"children":[{"text":""A \;\text{oder}\; B""}]},{"text":" eintritt, ist: "}]},{"type":"math","src":"P("A \;\text{oder}\; B") = P(A \cup B)","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Aber bei diesem Ereignis können auch "},{"type":"math","src":"A","inline":true,"children":[{"text":"A"}]},{"text":" und "},{"type":"math","src":"B","inline":true,"children":[{"text":"B"}]},{"text":" gleichzeitig auftreten."}]}],"id":"f2a8a5e0-b61d-4e06-a0e3-a47643c7ac56"},{"plugin":"box","state":{"type":"remember","title":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"22972827-045a-44b4-ac09-9f8de7eb0643"},"anchorId":"box80780","content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Das Ereignis "},{"type":"math","src":""A\;\text{oder}\;B"","inline":true,"children":[{"text":""A\;\text{oder}\;B""}]},{"text":" heißt immer: Es tritt "},{"type":"math","src":"A","inline":true,"children":[{"text":"A"}]},{"text":" ein oder es tritt "},{"type":"math","src":"B","inline":true,"children":[{"text":"B"}]},{"text":" ein oder es treten "},{"type":"math","src":"A","inline":true,"children":[{"text":"A"}]},{"text":" und "},{"type":"math","src":"B","inline":true,"children":[{"text":"B"}]},{"text":" gleichzeitig ein."}]}],"id":"dda51ae7-0cad-448b-bc59-188be3450c67"}],"id":"d5c2e1dc-d7da-4e7c-9ccb-1c1fd363be64"}},"id":"4d825afb-a5bc-4e48-bfe5-a80cf1d25ea6"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Das heißt, du musst von der Wahrscheinlichkeit "},{"type":"math","src":"P("A \;\text{oder}\; B")","inline":true,"children":[{"text":"P("A \;\text{oder}\; B")"}]},{"text":" noch die Wahrscheinlichkeit für das Ereignis "},{"type":"math","src":" "A \;\text{und}\; B \;\text{gleichzeitig}"","inline":true,"children":[{"text":""A und B \text{gleichzeitig}""}]},{"text":" abziehen, um auf das gewünschte Ergebnis zu kommen. Dafür musst du wissen: "}]},{"type":"math","src":"P( "A \;\text{und}\; B \;\text{gleichzeitig}") = P(A \cap B)","inline":false,"children":[{"text":""}]}],"id":"51e4b8e4-5d14-4b1a-ac5c-ac75efc22ade"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Also lautet das Endergebnis: "}]},{"type":"math","src":"\begin{array}{rcl}
&& P("\text{entweder}\; A\;\text{oder}\; B")\\ 
&=& P("A\;\text{oder}\; B") - P("A\;\text{und}\;B\; \text{gleichzeitig}")\\
 &=& P(A \cup B) - P(A \cap B)
\end{array}","inline":false,"children":[{"text":""}]}],"id":"c9a33843-0356-4f0a-bd6e-86d3df0e697b"}],"id":"2e22e4e9-5f85-422f-b360-a9a5397b3158"}},"id":"daba8d1c-074b-4892-91bf-bae723a6b64f"}},"id":"36014f1e-aa5d-493a-92d7-f8d22f499c7f"}}
